import unittest
from report.csvout import to_csv
from report.jsonout import to_json


class T(unittest.TestCase):
    def test_csv(self):
        self.assertEqual(to_csv([["a b", "c,d"]]), "a b,c;d")

    def test_json(self):
        self.assertEqual(to_json([["x  y", "1,2"]]), '[["x y", "1;2"]]')
